#!/usr/bin/env python3
"""
Converts all_175_prepinsta.json into the official TypeScript file:
src/data/top100Data.ts
"""
import json

with open('scratch/all_175_prepinsta.json', encoding='utf-8') as f:
    questions = json.load(f)

ts_header = """/**
 * top100Data.ts
 * Autogenerated database of all 175 PrepInsta coding challenges across all 8 syllabus sections.
 * 
 * Sections:
 * 1. Getting Started (28)
 * 2. Working with Numbers (26)
 * 3. Recursion (19)
 * 4. Arrays (32)
 * 5. Strings (22)
 * 6. Advanced Arrays (29)
 * 7. Matrix (9)
 * 8. Pattern Printing (10)
 */

export interface Top100Question {
  id: number;
  title: string;
  category: string;
  difficulty: 'Easy' | 'Medium' | 'Hard';
  statement: string;
  inputFormat: string;
  outputFormat: string;
  examples: {
    input: string;
    output: string;
    explanation?: string;
  }[];
  hint1: string;
  hint2: string;
  solution: {
    python: string;
    cpp: string;
    java: string;
    javascript: string;
  };
  boilerplate: {
    python: string;
    cpp: string;
    java: string;
    javascript: string;
  };
}

export const TOP_100_QUESTIONS: Top100Question[] = """

ts_content = ts_header + json.dumps(questions, indent=2) + ";\n"

with open('src/data/top100Data.ts', 'w', encoding='utf-8') as f:
    f.write(ts_content)

print(f"Generated src/data/top100Data.ts with {len(questions)} questions!")
